  const mockObserve = jest.fn();
  const mockDisconnect = jest.fn();
  const mockUnobserve = jest.fn();

  const ResizeObserverMock = jest.fn((fn) => {
    _resizeObserverCallbackFn = fn;

    return {
      observe: mockObserve,
      disconnect: () => {
        _resizeObserverCallbackFn = null;
